tool_input.new_string:
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL ?? 'postgres://localhost/demo' });

export const db = drizzle({ client: pool });

export async function findUser(id: number) {
  return db.query.users.findFirst({ where: (u, { eq }) => eq(u.id, id) });
}

// Ends the pool directly: db.$client.end() is mistyped in drizzle-orm 0.36.0 (drizzle-orm#3402).
export async function closeDb() {
  await pool.end();
}
